import{U as e,W as t,nt as n,t as r}from"./chunks/framework.BPwQCpO3.js";var i=JSON.parse(`{"title":"Anthropic Claude (BYOK Provider)","description":"","frontmatter":{"title":"Anthropic Claude (BYOK Provider)"},"headers":[],"relativePath":"providers/claude.md","filePath":"providers/claude.md"}`),a={name:`providers/claude.md`};function o(r,i,a,o,s,c){return n(),e(`div`,null,[...i[0]||=[t(`<h1 id="anthropic-claude-mode-byok" tabindex="-1">Anthropic Claude (Mode BYOK) <a class="header-anchor" href="#anthropic-claude-mode-byok" aria-label="Permalink to “Anthropic Claude (Mode BYOK)”">​</a></h1><p><strong>Anthropic Claude</strong> pilihan kuat untuk BYOK kalau kamu cari kualitas tulisan yang halus dan &quot;berasa&quot;: keluarga modelnya terkenal jago dalam <em>roleplay</em> naratif, mengikuti instruksi panjang dengan patuh, dan menjaga konsistensi karakter di percakapan yang panjang. Konsekuensinya: tidak ada <em>free tier</em> seperti Gemini, jadi siapkan kartu pembayaran di Claude Console. Kalau kamu baru mengenal BYOK, baca dulu <a href="./../byok/">Pengenalan BYOK</a>.</p><div class="warning custom-block"><p class="custom-block-title">📅 Info penting 2026</p><p>Claude Console kini berada di <strong>platform.claude.com</strong> (domain lama console.anthropic.com mengarah ke sana). Halaman ini mengajarkan <strong>cara</strong> yang benar, bukan daftar harga — angka harga dan limit berubah sering. Cek halaman resmi <a href="https://www.anthropic.com/pricing" target="_blank" rel="noreferrer">harga Anthropic</a> sebelum menetapkan budget.</p></div><hr><h2 id="membuat-api-key" tabindex="-1">Membuat API Key <a class="header-anchor" href="#membuat-api-key" aria-label="Permalink to “Membuat API Key”">​</a></h2><ol><li>Sign in di <strong>Claude Console</strong>, lalu buka <a href="https://platform.claude.com/settings/keys" target="_blank" rel="noreferrer">halaman API keys</a>.</li><li>Klik <strong>Create key</strong>, beri nama, pilih <strong>expiration</strong>, dan pilih akun yang ditautkan (<em>personal</em> atau <em>service account</em>).</li><li>Salin key yang ditampilkan — formatnya diawali <code>sk-ant-</code>.</li></ol><div class="danger custom-block"><p class="custom-block-title">🔒 Key only ditampilkan SEKALI</p><p>Setelah pembuatan, key <code>sk-ant-...</code> hanya ditampilkan <strong>satu kali</strong>. Salin langsung ke tempat aman (password manager) sebelum menutup dialog. Kalau terlewat, satu-satunya solusi adalah <strong>membuat key baru</strong>.</p></div><div class="tip custom-block"><p class="custom-block-title">Pilih key &quot;personal&quot;</p><p>Dua tipe key yang relevan: <strong>personal</strong> (terikat ke dirimu; berhenti bekerja kalau kamu keluar dari organisasi) dan <strong>service account</strong> (untuk workload otomatis/CI). Untuk BYOK pribadi, pilih <strong>personal key</strong> — sederhana dan cukup. <em>Workspace key</em> itu legacy, hindari.</p></div><details class="details custom-block"><summary>Tombol Create key ter-<em>disabled</em>?</summary><p>Artinya role kamu di organisasi tidak memadai untuk membuat key. Minta admin organisasi menaikkan role-mu, atau minta admin membuat / memberi akses <strong>service account</strong> yang bisa membawa key sendiri.</p></details><hr><h2 id="mengaktifkan-claude-di-mikazuki-ai" tabindex="-1">Mengaktifkan Claude di Mikazuki AI <a class="header-anchor" href="#mengaktifkan-claude-di-mikazuki-ai" aria-label="Permalink to “Mengaktifkan Claude di Mikazuki AI”">​</a></h2><p>Ikuti alur BYOK standar dari panduan <a href="./../byok/instalasi.html">Instalasi &amp; Aktivasi</a>. Ringkasannya untuk Claude:</p><ol><li>Buka <strong>Settings → Engine</strong>, pilih mode <strong>BYOK</strong>.</li><li>Pada pilihan provider, pilih <strong>Anthropic Claude</strong>.</li><li>Tempel API key <code>sk-ant-...</code> yang barusan kamu buat.</li><li>Klik tombol 🔍 <strong>fetch models</strong> — daftar model akan muncul otomatis dari key kamu.</li><li>Pilih model, atur <a href="./../byok/parameter-dasar.html">Parameter Dasar</a>, lalu klik simpan.</li></ol><p>Worker Mikazuki memakai <strong>endpoint Anthropic native</strong>, jadi tidak ada kolom <em>Base URL</em> untuk diisi — titik akhirnya fixed. Ini bedanya dengan provider lain yang menawarkan mode <em>OpenAI Compatible</em>: untuk Claude, opsi itu belum tersedia (Anthropic tidak menyediakan endpoint OpenAI-compatible resmi).</p><hr><h2 id="rate-limit-spend-cap" tabindex="-1">Rate Limit &amp; Spend Cap <a class="header-anchor" href="#rate-limit-spend-cap" aria-label="Permalink to “Rate Limit &amp; Spend Cap”">​</a></h2><p>Satu hal yang paling sering mengejutkan pengguna Claude: <strong>batasan dihitung per organisasi, bukan per key</strong>. Satu organisasi (yang bisa memuat banyak key dan project) berbagi satu budget dan satu rate limit.</p><p>Dua jenis batas:</p><ul><li><strong>Spend limit bulanan</strong> — berdasarkan tier akun. Tier naik otomatis seiring pengeluaran: <em>Evaluation → Start (500 USD/bulan) → Build (1.000 USD/bulan) → Scale (200.000 USD/bulan) → Custom</em> (tanpa cap). Mentok cap? API mengembalikan HTTP 429 <code>enforced_spend_limit_reached</code> sampai awal bulan berikutnya.</li><li><strong>Rate limit menit-an</strong> — RPM (request per menit), ITPM (token input per menit), dan OTPM (token output per menit) yang ikut naik tiap tier.</li></ul><div class="info custom-block"><p class="custom-block-title">Pasang sendiri spend limit-mu</p><p>Kamu juga bisa menetapkan <strong>spend limit sendiri</strong> di <a href="https://platform.claude.com/settings/billing" target="_blank" rel="noreferrer">Billing page</a> sebagai rem tambahan, terlepas dari cap resmi tier organisasimu. Angka lengkap dan terkini tier ada di dokumentasi <a href="https://platform.claude.com/docs/en/api/rate-limits" target="_blank" rel="noreferrer">rate limits</a> resmi Anthropic.</p></div><hr><h2 id="free-tier-harga" tabindex="-1">Free Tier &amp; Harga <a class="header-anchor" href="#free-tier-harga" aria-label="Permalink to “Free Tier &amp; Harga”">​</a></h2><div class="warning custom-block"><p class="custom-block-title">Tidak ada free tier seperti Gemini</p><p>Berbeda dengan Gemini, Anthropic API umumnya <strong>memerlukan pembayaran aktif</strong> — daftar kartu di <a href="https://platform.claude.com/settings/billing" target="_blank" rel="noreferrer">Billing</a> sebelum bisa pakai API. Akun baru kadang mendapat kredit trial kecil; cek apakah akunmu memilikinya, tapi jangan harap bisa jalan lama gratis.</p></div><p>Harga per model dibedakan per juta token — <strong>output selalu jauh lebih mahal daripada input</strong> — dan bisa berubah kapan saja, jadi tautan resmi <a href="https://www.anthropic.com/pricing" target="_blank" rel="noreferrer">harga Anthropic</a> adalah sumber satu-satunya yang layak untuk angka. Untuk roleplay santai kamu tidak butuh model paling mahal:</p><ul><li><strong>Kelas menengah</strong> (contoh: Sonnet 5 atau satu generasi di atasnya) — sweet spot untuk <em>roleplay</em> harian; kualitas tulisan solid, biaya masuk akal.</li><li><strong>Kelas premium</strong> (contoh: Opus 5) — simpan untuk momen khusus atau story dengan nuansa yang berat dan kompleks.</li><li><strong>Kelas hemat</strong> (contoh: Haiku 5) — buat chat ringan, autosummary, atau eksperimen murah.</li></ul><hr><h2 id="max-tokens-tidak-menghukum-rate-limit-output" tabindex="-1"><code>max_tokens</code> Tidak Menghukum Rate Limit Output <a class="header-anchor" href="#max-tokens-tidak-menghukum-rate-limit-output" aria-label="Permalink to “max_tokens Tidak Menghukum Rate Limit Output”">​</a></h2><p>Bonus kecil tapi enak dari rate limiting Anthropic: <strong>OTPM hanya menghitung token yang benar-benar dihasilkan</strong> — parameter <code>max_tokens</code> <em>tidak</em> ikut dihitung. Jadi menaikkan <code>max_tokens</code> di <a href="./../byok/parameter-dasar.html">Parameter Dasar</a> untuk memberi ruang jawaban panjang <strong>tidak menambah konsumsi rate limit output-mu</strong>.</p><p>(Sisi input juga punya bonus serupa untuk banyak model: token yang dibaca dari cache tidak dihitung ke ITPM — jarang relevan untuk aplikasi chat seperti ini, tapi menarik untuk diketahui.)</p><p>Jadi beda dengan Gemini, jawaban terpotong saat memakai Claude cenderung berarti <code>max_tokens</code>-mu perlu dinaikkan — bukan soal limit milik project.</p><hr><h2 id="troubleshooting" tabindex="-1">Troubleshooting <a class="header-anchor" href="#troubleshooting" aria-label="Permalink to “Troubleshooting”">​</a></h2><details class="details custom-block"><summary>Error 401 — key tidak valid</summary><p>Key salah tempel, terpotong saat salin, atau sudah lewat masa <em>expiration</em>-nya. Buka <a href="https://platform.claude.com/settings/keys" target="_blank" rel="noreferrer">halaman API keys</a>, hapus key lama jika ragu, lalu buat ulang dan tempel dengan rapi.</p></details><details class="details custom-block"><summary>Error 429 — rate limit / spend limit</summary><p>Ini limit <strong>per organisasi</strong>, bukan per key — membuat key baru tidak menolong. Cek dua hal: rate limit menit-an (tunggu sejenak dan coba lagi, atau naik tier lewat pengeluaran) atau <code>enforced_spend_limit_reached</code> (spend cap bulanan mentok; tunggu reset awal bulan berikutnya).</p></details><details class="details custom-block"><summary>Daftar model tidak muncul / kosong saat fetch</summary><p>Biasanya key memang valid tapi terkait workspace yang salah scope, atau pembacaan daftar model-nya gagal sesaat (error lookup). Pastikan key terkait workspace dengan akses ke model, lalu coba isi nama model secara <strong>manual</strong> di kolom model Mikazuki kalau fetch tetap gagal.</p></details><details class="details custom-block"><summary>Jawaban terpotong / berhenti di tengah</summary><p><code>max_tokens</code> di <a href="./../byok/parameter-dasar.html">Parameter Dasar</a> mungkin terlalu kecil. Naikkan nilainya tanpa ragu: <code>max_tokens</code> untuk Claude <strong>tidak ikut dihitung</strong> dalam rate limit output (lihat bagian di atas), jadi tidak menghukung kuota menit-anmu. Kalau sudah naik tapi jawaban tetap terpotong, periksa juga bahwa model yang dipilih bukan kelas hemat dengan gaya jawaban pendeknya sendiri.</p></details><details class="details custom-block"><summary>Tagihan di akhir bulan membesar</summary><p>Pasang <strong>spend limit sendiri</strong> di <a href="https://platform.claude.com/settings/billing" target="_blank" rel="noreferrer">Billing page</a> sebagai rem tambahan, pakai kelas model hemat (Haiku) untuk chat harian, dan tinjau <a href="https://www.anthropic.com/pricing" target="_blank" rel="noreferrer">harga resmi</a> berkala karena angka bisa bergeser.</p></details><hr><h2 id="jelajahi-byok-lebih-lanjut" tabindex="-1">Jelajahi BYOK Lebih Lanjut <a class="header-anchor" href="#jelajahi-byok-lebih-lanjut" aria-label="Permalink to “Jelajahi BYOK Lebih Lanjut”">​</a></h2><ul><li><a href="./../byok/">Pengenalan BYOK</a> — konsep dasar dan cara kerjanya.</li><li><a href="./../byok/instalasi.html">Instalasi &amp; Aktivasi</a> — langkah menyalakan mode BYOK.</li><li><a href="./../byok/parameter-dasar.html">Parameter Dasar</a> — atur <code>max_tokens</code>, <code>context_window</code>, dan parameter kreativitas.</li><li><a href="./gemini.html">Google Gemini</a> — panduan padanan untuk provider Gemini.</li><li><a href="./systemai.html">System AI</a> — kalau kamu tidak ingin mengurus key dan pembayaran API sendiri.</li></ul>`,40)]])}var s=r(a,[[`render`,o]]);export{i as __pageData,s as default};